import React, { useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';

const CourseStudentDetails = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const course = location.state?.course;

  const [formData, setFormData] = useState({ 
    name: '', 
    email: '', 
    phone: '',
    qualification: '',
    employmentStatus: '',
    degree: '',
    year: ''
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    // Pass both course and expanded student details to the payment screen
    navigate('/payment', { state: { course, student: formData } });
  };

  if (!course) return <p className="p-8">No course selected. Please go back.</p>;

  return (
    <div className="p-8 max-w-md mx-auto mt-10 border rounded-lg shadow-md bg-white text-gray-900">
      <h2 className="text-2xl font-bold mb-6">Student Details</h2>
      <p className="mb-4 text-gray-700">Enrolling in: <strong>{course.title}</strong></p>
      
      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label className="block mb-1 font-medium">Full Name</label>
          <input required type="text" name="name" onChange={handleChange} className="w-full border p-2 rounded" />
        </div>
        
        <div>
          <label className="block mb-1 font-medium">Email Address</label>
          <input required type="email" name="email" onChange={handleChange} className="w-full border p-2 rounded" />
        </div>
        
        <div>
          <label className="block mb-1 font-medium">Phone Number</label>
          <input required type="tel" name="phone" onChange={handleChange} className="w-full border p-2 rounded" />
        </div>

        <div>
          <label className="block mb-1 font-medium">Highest Qualification</label>
          <input required type="text" name="qualification" placeholder="e.g. Post Graduation" onChange={handleChange} className="w-full border p-2 rounded" />
        </div>

        <div>
          <label className="block mb-1 font-medium">Degree</label>
          <input required type="text" name="degree" placeholder="e.g. B.Tech / MCA / B.Sc" onChange={handleChange} className="w-full border p-2 rounded" />
        </div>

        <div>
          <label className="block mb-1 font-medium">Year of Passing / Current Year</label>
          <select required name="year" onChange={handleChange} className="w-full border p-2 rounded bg-white">
            <option value="">Select Year</option>
            <option value="1st Year">1st Year</option>
            <option value="2nd Year">2nd Year</option>
            <option value="3rd Year">3rd Year</option>
            <option value="4th Year">4th Year</option>
            <option value="2024">Passed out</option>
          </select>
        </div>

        <div>
          <label className="block mb-1 font-medium">Employment Status</label>
          <select required name="employmentStatus" onChange={handleChange} className="w-full border p-2 rounded bg-white">
            <option value="">Select Status</option>
            <option value="Student">Student</option>
            <option value="Job Holder">Job Holder</option>
            <option value="Freelancer">Freelancer</option>
            <option value="Unemployed">Looking for Job</option>
          </select>
        </div>

        <button type="submit" className="w-full bg-blue-600 text-white py-2 rounded mt-6 font-semibold hover:bg-blue-700 transition-colors">
          Proceed to Payment
        </button>
      </form>
    </div>
  );
};

export default CourseStudentDetails;
